{"code":"def transform(grid):
    a=[r[:] for r in grid]
    H=len(a); W=len(a[0])
    seen=set(); rects=[]
    for r in range(H):
      for c in range(W):
        if a[r][c]!=1 or (r,c) in seen: continue
        # component bbox
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          x,y=stack.pop(); cells.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<H and 0<=ny<W and a[nx][ny]==1 and (nx,ny) not in seen:
              seen.add((nx,ny)); stack.append((nx,ny))
        r0=min(x for x,y in cells); r1=max(x for x,y in cells)
        c0=min(y for x,y in cells); c1=max(y for x,y in cells)
        # complete rectangular border, with odd outer dimensions
        if (r1-r0+1)%2==1 and (c1-c0+1)%2==1:
          if all((x in (r0,r1) or y in (c0,c1)) for x,y in cells):
            rects.append(((r0+r1)//2,(c0+c1)//2))
    for cr,cc in rects:
      for c in range(W):
        if a[cr][c]==8: a[cr][c]=6
      for r in range(H):
        if a[r][cc]==8: a[r][cc]=6
    return a"}

